WFJ.Data.add("gossip", {
  ["6803f1cce2ea6304"] = { "Ho corso per queste pianure per molte, molte stagioni. E ho cacciato grandi bestie. E nessuno mi aveva mai battuto... finché non ho affrontato Ghost Howl.\n\nTanto tempo fa, l'enorme lupo era un alleato dei tauren e combatté con coraggio contro la Legione Infuocata. Ma fu ferito selvaggiamente da un demone, e lo squarcio nella sua carne non guarì mai. Alla fine... fece impazzire Ghost Howl.\n\nOra vaga per le pianure in agonia, cercando una fine al suo dolore. A mia vergogna, quando ci scontrammo non ebbi la forza di ucciderlo...", "." },
  ["68100666fa91aed3"] = { "Fuggite finché ne avete la possibilità, mortali. Pregherete per una morte rapida se scenderò nell'arena.", "." },
  ["6813c79514c114f7"] = { "Tu! Controlla quel rumore.", "." },
  ["681e966cfb66f984"] = { "Flagello avvistato nelle vicinanze!", "." },
  ["681eea7cc367a827"] = { "Lascia che ti spieghi un po' di matematica: «goblin» più «ingegneria» fa SAPER FARE, tesoro. Chi ti dice il contrario semplicemente non sa fare le addizioni.", "." },
  ["681efcd40d205298"] = { "Dobbiamo scoprire cosa danno da mangiare i Qiraji a quei mostri! Guarda quanto sono grossi!", "." },
  ["681fa63de399387b"] = { "Quando non hai un guaritore che curi le tue ferite, la conoscenza del ⟦First Aid=Primo Soccorso⟧ può salvarti la vita. Ti consiglio di rivolgerti a Dannelor, alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, per imparare quest'abilità.", "." },
  ["6837569f67fee7c2"] = { "%s cade su un ginocchio, allo stremo.", "." },
  ["6837982fd13ff221"] = { "Voglio restare qui a riflettere su ciò che abbiamo visto. Ti prego, va' da Erelas e raccontagli ciò che abbiamo scoperto.", "." },
  ["6839e249b6c84a45"] = { "Sarai un sacrificio degno!", "." },
  ["6839e256b6c84a52"] = { "Sarai un sacrificio degno.", "." },
  ["684d8ef7b323ea35"] = { "Oh, cielo! Guarda qui... tutte queste candele. Scommetto che servono per qualche rituale terribile o un'evocazione oscura. Meglio sbrigarci!", "." },
  ["684fab0085b08659"] = { "Questi frammenti mi fanno venire i brividi. Ehi, Greeby, hai trovato altre particelle?", "." },
  ["68532c8a2cc9b371"] = { "C-cosa vuoi? Lasciami in pace...", "." },
  ["685dbea346f31858"] = { "%s richiama altri alleati dall'ombra.", "." },
  ["685dfa7adf1c1c59"] = { "I Pilastri di Cristallo di Un'Goro sono un mistero per tutti. Per i pochi abitanti di qui sono fonte di leggende, e sul loro scopo si fanno molte congetture.", "." },
  ["686668c3a66fe805"] = { "%s si autodistrugge!", "." },
  ["6866f9a2454fd0f1"] = { "Ehi! Sei qui per una partita a nocche?", "." },
  ["68731898241737de"] = { "%s prepara una porzione di alette di poiana piccanti per {name}.", "." },
  ["687b29c1a1f9b682"] = { "|cffffff00La Torre Passo Nord è stata presa dall'⟦Horde=Orda⟧!|r", "." },
  ["687c3574bac76b4d"] = { "È un tentativo di salvataggio! Uccideteli tutti!", "." },
  ["687f27e9071103c7"] = { "Hai già addomesticato l'Ice Claw Bear?", "." },
  ["6881870c711e283c"] = { "Consideralo fatto, Jeztor. Dammi un segnalatore.", "." },
  ["68827e303e7a6504"] = { "%s inizia a fabbricare...", "." },
  ["6897c3475726ef54"] = { "Teletrasportami nella tana degli Imperatori Gemelli, per favore.", "." },
  ["689ac350516217ba"] = { "Ho bisogno di addestramento, signore!", "." },
  ["68aeb9550a8a83a2"] = { "Lunga vita al potente clan ⟦Blackrock=Roccianera⟧!", "." },
  ["68b33db5d6ccc704"] = { "C'è qualcosa che posso aiutarti a trovare?", "." },
  ["68ba633d66b9fbfc"] = { "Merce in vendita! Merce in vendita! Venite a vedere la merce di Antonio prima che debba andarmene, cittadini di ⟦Goldshire=Borgodoro⟧!", "." },
  ["68c14849f62f93d3"] = { "Sono fuoco eterno. Rinasco per sempre e sarò la luce che ti guiderà quando il freddo sarà più intenso.", "." },
  ["68c331fdae09355e"] = { "Come sarebbe a dire cosa intendo? È andata fuori di testa! La ragazza è impazzita del tutto. Di solito non picchio le ragazze, ma una volta tornati i sensi mi è salita una rabbia tremenda. Brann, Rutgar, io e la scimmia ci siamo scagliati su di lei come orchi! È un miracolo che siamo riusciti a respingerla. Sembrava quasi posseduta!", "." },
  ["68cad18d52b40a00"] = { "Salve, {class}. Scusami, ma sto conversando con Rimblat. Crede che persino questa terra si possa ancora salvare.", "." },
  ["68cf2a504189f7c1"] = { "Pagherai il prezzo più alto per questa insolenza, piccolo verme. La tua anima è mia!", "." },
  ["68d40a299d86fc1a"] = { "Sei qui per combattere per noi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧? Lok'tar Ogar, {class}!", "." },
  ["68f0f3f1112e24e5"] = { "Quell'infiltrato a ⟦Stonard=Pietrachiusa⟧ di sicuro... si aprirà... dopo aver bevuto il mio siero speciale. Ah ah!\n\nGli ingredienti necessari non sono affatto facili da procurare. Le pantere dell'ombra sono comuni nella palude, ma raccogliere abbastanza cuori per il nostro scopo può essere un'impresa. E il Signore del Brago sa essere una bestia così difficile.\n\nQuanto al tumore di Deepstrider, è terribilmente difficile da trovare. Ma la reazione chimica che ne posso ricavare non ha eguali.", "." },
  ["68f11a01cd5edd2f"] = { "Puoi dirlo! Quegli alveari brulicavano di silitidi di ogni tipo, per niente felici di vederci.\n\nAndava tutto bene finché non abbiamo trovato un cristallo coperto di glifi nell'⟦Hive'Regal=Alveare Regal⟧. Ne era attratta come una falena dalla fiamma! Ha appoggiato la sua bella guanciotta contro il cristallo ed è caduta all'istante in una specie di trance. Naturalmente la mia squadra si è preoccupata. L'abbiamo presa di peso e portata fuori di lì in tutta fretta!", "." },
  ["68fd9ff7db0c8c21"] = { "Per l'High Order!", "." },
  ["68ff7d461d5f5fce"] = { "Lizzarik ha lame. Lizzarik ha mazze. Lizzarik ha tutte le armi che ti servono, proprio qui!", "." },
})
